import{_ as a,o as t,c as s,a5 as l}from"./chunks/framework.a5no_H3L.js";const b=JSON.parse('{"title":"Classic Queue","description":"Classic Queue 是 RabbitMQ 最早的队列类型。理解它是理解 Quorum Queue 的基础。","frontmatter":{},"headers":[],"relativePath":"rabbitmq/03-queue/chapter-02-classic-queue.md","filePath":"rabbitmq/03-queue/chapter-02-classic-queue.md"}'),i={name:"rabbitmq/03-queue/chapter-02-classic-queue.md"};function c(u,e,r,n,d,p){return t(),s("div",null,[...e[0]||(e[0]=[l(`<h1 id="classic-queue" tabindex="-1" data-src-line="1" data-src-file="rabbitmq/03-queue/chapter-02-classic-queue.md">Classic Queue <a class="header-anchor" href="#classic-queue" aria-label="Permalink to &quot;Classic Queue&quot;">​</a></h1><blockquote data-src-line="3" data-src-file="rabbitmq/03-queue/chapter-02-classic-queue.md"><p data-src-line="3" data-src-file="rabbitmq/03-queue/chapter-02-classic-queue.md">Classic Queue 是 RabbitMQ 最早的队列类型。理解它是理解 Quorum Queue 的基础。</p></blockquote><h2 id="_1-classic-queue-的存储结构" tabindex="-1" data-src-line="5" data-src-file="rabbitmq/03-queue/chapter-02-classic-queue.md">1. Classic Queue 的存储结构 <a class="header-anchor" href="#_1-classic-queue-的存储结构" aria-label="Permalink to &quot;1. Classic Queue 的存储结构&quot;">​</a></h2><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌──────────────────────────────────────────┐</span></span>
<span class="line"><span>│            Classic Queue                 │</span></span>
<span class="line"><span>│                                          │</span></span>
<span class="line"><span>│  ┌─────────────────────────────────────┐ │</span></span>
<span class="line"><span>│  │  Q1 (内存，未消费)                   │ │</span></span>
<span class="line"><span>│  │  [msg1][msg2][msg3]                 │ │</span></span>
<span class="line"><span>│  └─────────────────────────────────────┘ │</span></span>
<span class="line"><span>│  ┌─────────────────────────────────────┐ │</span></span>
<span class="line"><span>│  │  Q2 (内存引用，指向磁盘)               │ │</span></span>
<span class="line"><span>│  │  [ref1][ref2][ref3]                 │ │</span></span>
<span class="line"><span>│  └─────────────────────────────────────┘ │</span></span>
<span class="line"><span>│  ┌─────────────────────────────────────┐ │</span></span>
<span class="line"><span>│  │  Delta (磁盘，未读)                   │ │</span></span>
<span class="line"><span>│  │  [msg4][msg5][msg6]...              │ │</span></span>
<span class="line"><span>│  └─────────────────────────────────────┘ │</span></span>
<span class="line"><span>│  ┌─────────────────────────────────────┐ │</span></span>
<span class="line"><span>│  │  Q3 (磁盘索引)                       │ │</span></span>
<span class="line"><span>│  └─────────────────────────────────────┘ │</span></span>
<span class="line"><span>└──────────────────────────────────────────┘</span></span></code></pre></div><p data-src-line="29" data-src-file="rabbitmq/03-queue/chapter-02-classic-queue.md">Classic Queue 使用一种混合存储：热数据在内存（Q1），冷数据在磁盘（Delta），中间有索引（Q2/Q3）。</p><p data-src-line="31" data-src-file="rabbitmq/03-queue/chapter-02-classic-queue.md">上面的 Q1/Q2/Delta/Q3 是特定历史实现的简化模型，不是所有版本的通用布局。Classic Queue 存储实现有版本演进：CQv2（Classic Queue version 2）在 RabbitMQ 3.10 引入，3.12 起成为新建队列的默认实现。排查内存占用、磁盘 I/O 与消息堆积时，应以目标版本的实际行为为准。</p><h2 id="_2-消息流转" tabindex="-1" data-src-line="33" data-src-file="rabbitmq/03-queue/chapter-02-classic-queue.md">2. 消息流转 <a class="header-anchor" href="#_2-消息流转" aria-label="Permalink to &quot;2. 消息流转&quot;">​</a></h2><p data-src-line="35" data-src-file="rabbitmq/03-queue/chapter-02-classic-queue.md">下面的流转同样基于 §1 的历史实现模型，不代表当前所有版本的通用行为。</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>消息进入 → Q1（内存）</span></span>
<span class="line"><span>  │</span></span>
<span class="line"><span>  ├─ 内存够 → 一直在 Q1，直接消费</span></span>
<span class="line"><span>  └─ 内存不够 → 换页到磁盘（Delta），Q2 存引用</span></span>
<span class="line"><span>  </span></span>
<span class="line"><span>消费时：</span></span>
<span class="line"><span>  Q1 有消息 → 直接从 Q1 取</span></span>
<span class="line"><span>  Q1 空了 → 从 Delta 读磁盘 → 加载到 Q1</span></span></code></pre></div><h2 id="_3-classic-queue-的局限" tabindex="-1" data-src-line="48" data-src-file="rabbitmq/03-queue/chapter-02-classic-queue.md">3. Classic Queue 的局限 <a class="header-anchor" href="#_3-classic-queue-的局限" aria-label="Permalink to &quot;3. Classic Queue 的局限&quot;">​</a></h2><table tabindex="0"><thead data-src-line="50" data-src-file="rabbitmq/03-queue/chapter-02-classic-queue.md"><tr data-src-line="50" data-src-file="rabbitmq/03-queue/chapter-02-classic-queue.md"><th style="text-align:left;">问题</th><th style="text-align:left;">说明</th></tr></thead><tbody data-src-line="52" data-src-file="rabbitmq/03-queue/chapter-02-classic-queue.md"><tr data-src-line="52" data-src-file="rabbitmq/03-queue/chapter-02-classic-queue.md"><td style="text-align:left;">镜像队列已移除</td><td style="text-align:left;">Classic Queue 镜像自 3.9 弃用、4.0 移除；Quorum Queue 自 3.8 引入，成为高可用方案</td></tr><tr data-src-line="53" data-src-file="rabbitmq/03-queue/chapter-02-classic-queue.md"><td style="text-align:left;">内存瓶颈</td><td style="text-align:left;">消息堆积时换页到磁盘，消费性能下降</td></tr><tr data-src-line="54" data-src-file="rabbitmq/03-queue/chapter-02-classic-queue.md"><td style="text-align:left;">无队列级速率整形</td><td style="text-align:left;">生产速度远大于消费速度时消息持续堆积；队列本身不自动整形生产速率。内存达高水位时 Broker 对发布端限速，磁盘空间不足时触发告警并阻塞发布</td></tr><tr data-src-line="55" data-src-file="rabbitmq/03-queue/chapter-02-classic-queue.md"><td style="text-align:left;">故障恢复</td><td style="text-align:left;">Broker 崩溃后需从磁盘恢复索引与消息状态，恢复耗时与消息量、持久化配置相关</td></tr></tbody></table><h2 id="_4-classic-queue-参数" tabindex="-1" data-src-line="57" data-src-file="rabbitmq/03-queue/chapter-02-classic-queue.md">4. Classic Queue 参数 <a class="header-anchor" href="#_4-classic-queue-参数" aria-label="Permalink to &quot;4. Classic Queue 参数&quot;">​</a></h2><p data-src-line="59" data-src-file="rabbitmq/03-queue/chapter-02-classic-queue.md">以下为常用队列声明参数简表。</p><table tabindex="0"><thead data-src-line="61" data-src-file="rabbitmq/03-queue/chapter-02-classic-queue.md"><tr data-src-line="61" data-src-file="rabbitmq/03-queue/chapter-02-classic-queue.md"><th style="text-align:left;">参数</th><th style="text-align:left;">默认值</th><th style="text-align:left;">说明</th></tr></thead><tbody data-src-line="63" data-src-file="rabbitmq/03-queue/chapter-02-classic-queue.md"><tr data-src-line="63" data-src-file="rabbitmq/03-queue/chapter-02-classic-queue.md"><td style="text-align:left;">x-max-length</td><td style="text-align:left;">不限</td><td style="text-align:left;">Queue 最大消息数</td></tr><tr data-src-line="64" data-src-file="rabbitmq/03-queue/chapter-02-classic-queue.md"><td style="text-align:left;">x-max-length-bytes</td><td style="text-align:left;">不限</td><td style="text-align:left;">Queue 最大字节数</td></tr><tr data-src-line="65" data-src-file="rabbitmq/03-queue/chapter-02-classic-queue.md"><td style="text-align:left;">x-overflow</td><td style="text-align:left;">drop-head</td><td style="text-align:left;">超限时行为：drop-head（丢队头）/ reject-publish / reject-publish-dlx</td></tr><tr data-src-line="66" data-src-file="rabbitmq/03-queue/chapter-02-classic-queue.md"><td style="text-align:left;">x-message-ttl</td><td style="text-align:left;">不限</td><td style="text-align:left;">消息 TTL（毫秒）</td></tr><tr data-src-line="67" data-src-file="rabbitmq/03-queue/chapter-02-classic-queue.md"><td style="text-align:left;">x-expires</td><td style="text-align:left;">不限</td><td style="text-align:left;">Queue 一段时间未使用后自动删除</td></tr><tr data-src-line="68" data-src-file="rabbitmq/03-queue/chapter-02-classic-queue.md"><td style="text-align:left;">x-max-priority</td><td style="text-align:left;">未启用</td><td style="text-align:left;">最大优先级；启用时设为正整数</td></tr><tr data-src-line="69" data-src-file="rabbitmq/03-queue/chapter-02-classic-queue.md"><td style="text-align:left;">x-dead-letter-exchange</td><td style="text-align:left;">无</td><td style="text-align:left;">死信 Exchange</td></tr><tr data-src-line="70" data-src-file="rabbitmq/03-queue/chapter-02-classic-queue.md"><td style="text-align:left;">x-dead-letter-routing-key</td><td style="text-align:left;">未指定</td><td style="text-align:left;">死信 routing key；未指定时保留原 routing key，显式配置则覆盖</td></tr></tbody></table><h2 id="_5-什么时候还用-classic-queue" tabindex="-1" data-src-line="72" data-src-file="rabbitmq/03-queue/chapter-02-classic-queue.md">5. 什么时候还用 Classic Queue <a class="header-anchor" href="#_5-什么时候还用-classic-queue" aria-label="Permalink to &quot;5. 什么时候还用 Classic Queue&quot;">​</a></h2><ul data-src-line="74" data-src-file="rabbitmq/03-queue/chapter-02-classic-queue.md"><li data-src-line="74" data-src-file="rabbitmq/03-queue/chapter-02-classic-queue.md">已有系统在用 Classic Queue，且运行稳定</li><li data-src-line="75" data-src-file="rabbitmq/03-queue/chapter-02-classic-queue.md">不需要高可用（单节点场景）</li><li data-src-line="76" data-src-file="rabbitmq/03-queue/chapter-02-classic-queue.md">临时队列（排他、自动删除）</li><li data-src-line="77" data-src-file="rabbitmq/03-queue/chapter-02-classic-queue.md">需要优先级队列（Classic Queue 原生支持 x-max-priority）</li></ul><p data-src-line="79" data-src-file="rabbitmq/03-queue/chapter-02-classic-queue.md"><strong>需要复制与节点故障后的高可用时，优先考虑 Quorum Queue；临时、排他或不需要复制的队列，仍可用 Classic Queue。</strong></p><h2 id="_6-classic-queue-vs-quorum-queue" tabindex="-1" data-src-line="81" data-src-file="rabbitmq/03-queue/chapter-02-classic-queue.md">6. Classic Queue vs Quorum Queue <a class="header-anchor" href="#_6-classic-queue-vs-quorum-queue" aria-label="Permalink to &quot;6. Classic Queue vs Quorum Queue&quot;">​</a></h2><table tabindex="0"><thead data-src-line="83" data-src-file="rabbitmq/03-queue/chapter-02-classic-queue.md"><tr data-src-line="83" data-src-file="rabbitmq/03-queue/chapter-02-classic-queue.md"><th style="text-align:left;">维度</th><th style="text-align:left;">Classic Queue</th><th style="text-align:left;">Quorum Queue</th></tr></thead><tbody data-src-line="85" data-src-file="rabbitmq/03-queue/chapter-02-classic-queue.md"><tr data-src-line="85" data-src-file="rabbitmq/03-queue/chapter-02-classic-queue.md"><td style="text-align:left;">高可用</td><td style="text-align:left;">无内置复制（镜像已移除）</td><td style="text-align:left;">Raft 多数派复制</td></tr><tr data-src-line="86" data-src-file="rabbitmq/03-queue/chapter-02-classic-queue.md"><td style="text-align:left;">数据持久化</td><td style="text-align:left;">队列需声明 durable，消息需设 deliveryMode=2</td><td style="text-align:left;">队列默认 durable，消息经多数派复制后确认</td></tr><tr data-src-line="87" data-src-file="rabbitmq/03-queue/chapter-02-classic-queue.md"><td style="text-align:left;">性能</td><td style="text-align:left;">无共识开销；实际吞吐与延迟需在目标负载下测量</td><td style="text-align:left;">Raft 共识有开销；实际吞吐与延迟需在目标负载下测量</td></tr><tr data-src-line="88" data-src-file="rabbitmq/03-queue/chapter-02-classic-queue.md"><td style="text-align:left;">数据安全</td><td style="text-align:left;">队列数据不复制，节点丢失即丢失</td><td style="text-align:left;">消息被多数副本接收后才向发布者确认；已确认消息在多数派存活的前提下安全</td></tr><tr data-src-line="89" data-src-file="rabbitmq/03-queue/chapter-02-classic-queue.md"><td style="text-align:left;">适用场景</td><td style="text-align:left;">临时、排他、单节点</td><td style="text-align:left;">生产环境、高可用</td></tr></tbody></table><p data-src-line="91" data-src-file="rabbitmq/03-queue/chapter-02-classic-queue.md">详细机制见 <a href="./chapter-03-quorum-queue.html">Quorum Queue</a>。</p>`,20)])])}const m=a(i,[["render",c]]);export{b as __pageData,m as default};
